"""Build the source-complete Clean Code excerpt course. Standard library only."""
from pathlib import Path
import hashlib, json, re

ROOT = Path(__file__).resolve().parents[1]
sections = []
coverage = []

def module(id, title):
    node = dict(id=id, type='section', title=title, children=[])
    sections.append(node)
    return node

def lesson(mod, id, title, pages, objective, points, practice, check):
    slides = [('Learning objective', objective + '\n\nSource: supplied Clean Code excerpt, PDF pages ' + pages + '. The following explanations and exercises are authored study material; the complete extracted source appears in module 08.')]
    slides += points
    slides += [('Practice', practice), ('Worked self-check', check)]
    node = dict(id=id, type='slides', title=title, slides=[dict(id=f'{id}-s{i}', title=t, body=b) for i,(t,b) in enumerate(slides,1)])
    mod['children'].append(node)
    coverage.append(dict(lessonId=id, sourcePages=pages, heading=title))
    return node

def quiz(mod, id, title, skill, questions):
    node = dict(id=id, type='quiz', title=title, skill=skill, questions=[dict(id=f'{id}-q{i}', prompt=p, options=o, answer=a, explanation=e) for i,(p,o,a,e) in enumerate(questions,1)])
    mod['children'].append(node)
    return node

m = module('orientation', '01 Start here')
lesson(m, 'start', 'Your learning path and source scope', '1–67',
       'Recognize what this excerpt actually contains and choose a short, active study session.', [
    ('What is available', 'This is the 67-page excerpt supplied for this course. It contains publication material and contents (PDF 1–18), James O. Coplien’s foreword (19–23), the introduction and acknowledgments (25–28), On the Cover (29), Chapter 1 Clean Code (31–45), the book index (47–65), and publisher registration and subscription offers (66–67). Pages 6, 18, 24, 30 and 46 contain intentional-blank notices.\n\nLater chapters are named in the contents and index but their actual explanations and case studies are absent. An index entry is a pointer, not a lesson from that missing chapter.'),
    ('How the lessons work', 'Modules 02–06 explain every substantive topic present in the foreword, introduction and Chapter 1. Each lesson has an objective, a focused explanation, a practice task and a worked check. Module 07 applies these ideas in an original JavaScript refactoring clinic. Module 08 preserves ALL extracted text, including credits, contents, index entries, footnotes and advertisements, in original page order.\n\nOriginal examples are labeled as course exercises. They are not listings from the book. The site does not run arbitrary code; use your own console or project.'),
    ('Choose a manageable session', 'Read one lesson, stop at Practice, and write your own explanation before revealing the worked check. In five to ten minutes you can improve one name, one boundary or one test. Then take the relevant module quiz.\n\nUse lesson notes for a Feynman explanation: What is this idea? Why does it matter? What example shows it? What part can I not explain yet?'),
    ('Progress and copying', 'All lessons and quizzes are open by default. Reports, notes and completion save only in this browser. Quizzes are study feedback, not secure exams. Passing is 80% and retakes are available.\n\nCopy entire course includes explanations, every source page, practice, answer choices and worked answers. It excludes your notes and progress. Settings can enable completion gates; with gates enabled, reference decks also count as lessons.')],
    'Find Chapter 1 and the full source reference in the outline. Name two topics this excerpt can teach and one later chapter it cannot reproduce.',
    'Available: the economics of messy code and the Boy Scout Rule. Not available as a chapter: Meaningful Names, Unit Tests or Concurrency. Their titles/index references do not substitute for their missing contents. Start with one short lesson rather than treating every reference page as a daily assignment.')
lesson(m, 'front-matter', 'Publication material and navigating the book', '1–18, 27–30, 45–67',
       'Use publication details, contents, bibliography and the index without mistaking navigation for missing teaching.', [
    ('Credits and provenance', 'Clean Code: A Handbook of Agile Software Craftsmanship is credited to Robert C. Martin and the Object Mentors. The title page names Michael C. Feathers, Timothy R. Ottinger, Jeffrey J. Langr, Brett L. Schuchert, James W. Grenning and Kevin Dean Wampler. The excerpt’s copyright page states © 2009 Pearson Education, Inc.; this printing is identified as January 2015.\n\nThe dedication, publisher contacts, ISBNs and series titles remain in the source reference. Acknowledgments credit artists Jeniffer Kohnke and Angela Brooks, reviewers, publishers, Object Mentors and other colleagues.'),
    ('The contents are a roadmap', 'The contents list the complete book’s chapters: Clean Code, Meaningful Names, Functions, Comments, Formatting, Objects and Data Structures, Error Handling, Boundaries, Unit Tests, Classes, Systems, Emergence, Concurrency, Successive Refinement, JUnit Internals, Refactoring SerialDate, and Smells and Heuristics, followed by the concurrency appendix and index.\n\nOnly Chapter 1 is present as chapter text in this upload. Use the contents to plan later reading; do not infer full rules from headings alone.'),
    ('Printed pages versus PDF pages', 'PDF page 31 is printed page 1. Roman-numbered front matter comes before it. The index starts at PDF page 47, printed page 413. An index reference such as 120 points to printed page 120 of the full book, not PDF page 120 or a page present in this excerpt.\n\nThe source reference labels the PDF page explicitly and retains printed numbers. Chapter 1’s bibliography names Kent Beck’s Implementation Patterns (2007) and Donald E. Knuth’s Literate Programming (1992).'),
    ('The cover essay', 'On the Cover identifies the cover subject as M104, the Sombrero Galaxy, and describes a visible-light Hubble and infrared Spitzer composite. It also contains the author’s imaginative comparison with science-fiction explosions and speculation about a central black hole. Treat that speculation as the author’s narrative, not as established astrophysical explanation.\n\nThe supplied course theme image is a separate color reference; it is not evidence for the cover essay. The essay, image credit and publisher registration offer and final Safari Books Online advertisement are preserved as source material.')],
    'An index says a topic appears on printed page 120. Can you open it in this 67-page course source? Explain the page-number distinction.',
    'No. The source jumps from Chapter 1 to the full book’s index; printed page 120 is not included. PDF page numbers locate available pages, while the index points into the full book. Use the relevant source page to inspect the entry, then obtain the missing chapter before claiming its detailed guidance.')

m = module('foreword', '02 Care and everyday discipline')
lesson(m, 'details', 'Small details and maintenance', '19–23',
       'Explain why everyday code care contributes to software quality alongside architecture.', [
    ('Small work supports large work', 'Coplien uses architecture and a licorice-box proverb to argue that small details matter. A well-planned building can still be undermined by a door that does not close; a well-planned system can still be undermined by careless names, layout and local decisions.\n\nPlanning and architecture remain useful. Attention to local construction gives a team the proficiency and trust needed for larger work.'),
    ('Production is only one part of the lifecycle', 'The foreword contrasts fast production with ongoing maintenance. Total Productive Maintenance (TPM) supplies a metaphor: do not wait for equipment to fail before caring for it. Inspect, prevent deterioration, and design for maintainability.\n\nCoplien’s statement that maintenance accounts for 80% or more of software work is a historical claim in this foreword, not a measured statistic about your current team.'),
    ('Preventive work and replacement', 'The maintenance analogy progresses from fixing failures to preventive inspection, making new systems maintainable, and eventually replacing obsolete equipment. In code, local refactoring can prevent a small problem from spreading.\n\nThe foreword also discusses replacement and a Brooks time interval; these are contextual arguments, not an instruction to rewrite a production application on a fixed calendar. Chapter 1 later explains the costs of an uncontrolled grand redesign.')],
    'Pick a small module you understand. Identify one detail that slows a reader and one larger structural concern. Which can you safely improve today?',
    'A vague variable name can be renamed with its references and checked immediately. A database boundary may require broader evidence and planning. Caring about the small issue supports larger design work; it does not prove that the architecture is already correct.')
lesson(m, 'five-s', 'The five maintenance disciplines', '20–21',
       'Translate the foreword’s 5S maintenance metaphor into concrete code habits.', [
    ('Organization and tidiness', '**Seiri — organization/sort:** know where things are; choose names that reveal meaning.\n\n**Seiton — tidiness/systematize:** keep a thing where readers expect to find it. If responsibility has wandered, consider refactoring it into the appropriate module.\n\nA reader should not have to search unrelated files for one concept.'),
    ('Cleaning and standardization', '**Seiso — cleaning/shine:** remove waste. The foreword specifically criticizes commented-out lines that preserve history or wishes. Version control is an appropriate place for history; active source should communicate current behavior.\n\n**Seiketsu — standardization:** agree as a team on consistent style and practices. A shared convention reduces avoidable surprises; agreement is more useful than each person imposing a private preference.'),
    ('Self-discipline', '**Shutsuke — self-discipline**, using the spelling in the supplied text: follow practices, reflect frequently and be willing to change.\n\nA cleanup that happens once is not a maintenance habit. Make small reviews repeatable. These are analogies from maintenance, not an automated scoring formula for code quality.')],
    'Classify these improvements using the five disciplines: clarify a name, move validation beside related validation, remove dead commented code, adopt a shared formatter, and review before every commit.',
    'Clarify a name: Seiri. Move related validation: Seiton. Remove dead commented code: Seiso. Agree on formatting: Seiketsu. Repeat the review habit and reflect on it: Shutsuke. The categories overlap; use them to guide care, not to argue about labels.')
lesson(m, 'honesty', 'Design as ongoing repair and honest quality', '21–23',
       'Connect refactoring, concrete design and an honest definition of done.', [
    ('Design continues after release', 'Coplien invokes Christopher Alexander’s local acts of repair and the continual rework of poetry. Design is a process rather than a finished drawing. Maintenance does not automatically mean failure; refining the design can add value.\n\nHis contrast is between wasteful manufacturing rework and valuable design refinement. The architectural relationship of coupling and cohesion becomes concrete in actual code.'),
    ('Consistency is useful evidence, not proof', 'The foreword recounts informal Bell Labs findings linking consistent indentation with lower bug density. Preserve the distinction: this is a reported historical observation, not proof that a formatter guarantees correctness or that indentation alone causes fewer bugs.\n\nLook at what the code does, how responsibilities fit together and whether a change can be safely checked.'),
    ('Be honest about the state of the code', 'The closing argument is honesty with yourself and colleagues. Make unfinished work visible; include refactoring in what your team means by Done when appropriate. Neither architecture nor clean code requires perfection.\n\nA useful report describes the issue, its consequence, the evidence and the remaining uncertainty. Quietly hiding a known shortcut makes the next person’s decisions harder.')],
    'Write a two-sentence status for code that passes the happy path but has no check for an empty input. Include the remaining work.',
    '“The normal input is covered and passes. Empty input behavior is not yet specified or tested; I will agree on that behavior and add a focused test before calling the change done.” This is more honest and useful than “Everything works.”')
quiz(m, 'care-check', 'Check everyday discipline', 'Care and maintenance', [
    ('Which action best demonstrates Seiton?', ['Make every name shorter', 'Place validation with the module responsible for it', 'Delay all cleanup until a rewrite'], 1, 'Seiton concerns expected location and organization of work; names alone are Seiri’s emphasis.'),
    ('What does the indentation anecdote establish?', ['Formatting guarantees correctness', 'All architectural decisions are irrelevant', 'The foreword reports an association; tests and design review still matter'], 2, 'An informal historical association does not prove causation or replace checking actual behavior.'),
    ('Which status best reflects honesty about quality?', ['Works on my example, so it is finished', 'Normal input passes; failure handling still needs verification', 'Do not mention incomplete checks'], 1, 'State what is known and what remains, so the team can make informed decisions.'),
    ('Which habit matches self-discipline?', ['Reviewing and refining work regularly', 'Applying standards only on release day', 'Choosing a different convention for each function'], 0, 'The foreword emphasizes sustained practices, reflection and willingness to change.')])

m = module('learning', '03 Learning the craft')
lesson(m, 'knowledge-work', 'Knowledge and deliberate practice', '25–28',
       'Distinguish knowing a principle from being able to apply it to real code.', [
    ('Two ingredients', 'The introduction says craftsmanship requires knowledge and work. Learning principles, patterns, practices and heuristics is necessary; applying them repeatedly is also necessary. Knowing the equations of a bicycle does not mean you can ride it.\n\nCode learning needs the equivalent of riding: read code, try a change, see what goes wrong, and revise your decision.'),
    ('Watch the decisions, not just the result', 'The author asks readers to observe successes, failures, reversals and the costs of bad choices. Read code closely enough to explain what is right and what is wrong. Follow how modules are taken apart and rebuilt.\n\nFor this excerpt, the original later case studies are unavailable. The course’s small JavaScript clinic is authored practice, not a replacement or reconstruction of those missing chapters.'),
    ('Make the work observable', 'Record the behavior before a change, the improvement you intend, the transformation, and the check afterward. If you cannot explain why the change is better, write down that gap and investigate.\n\nA useful five-minute exercise can be one function, one safe rename, or one explanation of a confusing branch. Completing slides is not evidence that you can refactor a real system.')],
    'Explain a function in your own words without editing it. Then predict the output for one normal case and one edge case, and check both in your environment.',
    'A good explanation names the inputs, output, assumptions and side effects. If a prediction fails, revise your mental model before refactoring. You are practicing understanding and feedback, rather than memorizing a slogan.')
lesson(m, 'heuristics-context', 'Principles, case studies and heuristics', '26–27',
       'Explain how the complete book connects general guidance with specific refactoring decisions.', [
    ('The book’s three parts', 'The introduction describes principles and practices first, detailed case studies second, and a collection of smells and heuristics third. The case studies grow in complexity and connect narrative decisions to code listings.\n\nThis upload gives the description of that structure, not the case-study chapters or the final heuristics chapter itself.'),
    ('A heuristic needs context', 'Forward references such as [H22] connect a particular change to a heuristic. A cross-reference at the end of the full book points back to every occurrence. The valuable knowledge is the relationship between the rule and the decision that prompted it.\n\nA rule without its trigger, assumptions and tradeoff can become a reflex applied in the wrong place.'),
    ('Turn a guideline into a decision record', 'Use four questions: What problem did I observe? Which transformation addresses it? What behavior must stay unchanged? How will I verify that?\n\nKeep the guideline as a reason to investigate. Do not invent the text of a numbered book heuristic from an isolated reference or index entry.')],
    'Take “reduce duplication.” Write a case where sharing logic helps and a case where combining two similar-looking functions would be premature.',
    'Sharing a genuinely identical permission rule can prevent updates from diverging. Combining two rules that only look similar but have different domain reasons can create a misleading abstraction. Explain the shared idea and expected change pattern before extracting it. This tradeoff discussion is authored guidance, not a quotation from an unavailable heuristic.')
quiz(m, 'learning-check', 'Check the learning method', 'Deliberate practice', [
    ('Why does the introduction compare coding with bicycle riding?', ['Reading equations is enough to master a skill', 'Knowledge must be paired with hands-on practice', 'Programming principles have no value'], 1, 'Principles matter, but repeated practice develops the ability to apply them.'),
    ('What makes a case-study heuristic useful?', ['Its relationship to a concrete decision and its context', 'Its short label alone', 'The assumption that it works everywhere'], 0, 'The introduction stresses seeing why a particular transformation was made.'),
    ('What does an index reference to a missing chapter provide?', ['That chapter’s full content', 'An executable example', 'A pointer into the full book, not the missing explanation'], 2, 'The index is retained completely, but absent chapters are not reconstructed as source text.')])

m = module('economics', '04 The cost of messy code')
lesson(m, 'precision', 'There will be code', '31–32',
       'Explain why tools and higher abstractions do not remove the need for precise requirements.', [
    ('Code expresses the details', 'Chapter 1 argues that executable specifications must be detailed, formal and accurate enough for a machine. Higher-level languages and domain-specific languages can raise abstraction, but cannot eliminate required precision.\n\nThe author’s prediction about the future is his position in this historical text. The practical lesson is to resolve ambiguous behavior instead of assuming a tool will infer every unstated need.'),
    ('A vague requirement hides choices', '“Only show completed lessons” leaves questions unanswered: Does completion mean visited or explicitly marked? Are quizzes included? What about missing completion data?\n\nAn authored JavaScript example makes one contract explicit:\n\n```js\nfunction getCompletedLessons(lessons) {\n  return lessons.filter(lesson => lesson.completed === true);\n}\n```\n\nThis treats only the boolean true as completed; it does not accept the string "true".'),
    ('Specify before generating or implementing', 'Write examples of accepted inputs and expected results, including edge cases. Those examples can become executable checks. A code generator or coding assistant still produces an implementation of a contract that someone must understand and review.\n\nThe source’s argument is about necessary precision, not proof that any particular modern tool succeeds or fails.')],
    'Specify getCompletedLessons for an empty array, completed false, missing completed, and completed "true". Should the function mutate the input?',
    'For the contract shown: empty input returns []; false, missing and the string "true" are excluded; only boolean true is included. filter returns a new array and does not mutate the input array. Invalid non-array input is outside this example’s stated contract and needs a separate decision.')
lesson(m, 'mess-cost', 'Bad code and the total cost of owning a mess', '33–34',
       'Trace how a convenient shortcut can turn into long-term difficulty changing a system.', [
    ('The product story', 'Martin recounts a popular product whose rushed implementation accumulated problems. Releases slowed, bugs persisted, load times grew and crashes increased. An employee later attributed the failure to an unmanageable codebase.\n\nThis is an anecdote in the source, not a controlled study or a claim that every business failure has the same cause.'),
    ('Wading and postponed cleanup', 'Wading describes trying to understand tangled code before a change. Deadline pressure, fatigue and a long backlog can encourage a working mess. The chapter names LeBlanc’s law: postponing cleanup indefinitely often means it never happens.\n\nA better decision names the specific debt, its consequence and the time or trigger for addressing it. An unspecified “later” is not a maintenance plan.'),
    ('The feedback loop', 'As tangles grow, a small change can break unrelated parts. More effort goes into understanding the mess. Management may add staff, but newcomers do not yet understand the design and feel the same pressure to ship. Their changes can add more disorder.\n\nFigure 1-1 illustrates productivity declining toward zero. It is a conceptual figure, not a dataset from which this course can calculate a numeric productivity forecast.')],
    'Describe a shortcut in an app you know. Map it through this chain: confusion → slower change → pressure → further shortcut. Give one intervention.',
    'Example: duplicated completion rules diverge, so updates require searching several files; a deadline encourages copying a fourth rule. An intervention is to agree on one explicit rule, test it, and route callers through it. The improvement must address observed behavior, not just reduce a line count.')
lesson(m, 'redesign', 'The grand redesign and professional responsibility', '35–36',
       'Explain rewrite risk and communicate code-quality consequences under deadline pressure.', [
    ('The replacement race', 'The “grand redesign” story splits a team into a new implementation group and maintainers of the old system. The replacement must match existing behavior while keeping up with ongoing changes. The finish line moves.\n\nMartin describes long projects in which a replacement becomes messy before it ships. The argument favors sustained care; it does not prove that every rewrite is wrong.'),
    ('Attitude and responsibility', 'The chapter criticizes blaming requirements, schedules or management while hiding technical consequences. Programmers participate in validating requirements, estimates and design choices. They should provide honest technical information and defend necessary engineering work.\n\nThe doctor/hand-washing analogy emphasizes explaining risks when the person requesting speed lacks that expertise. It is an analogy, not a software regulation.'),
    ('The primal conundrum', 'Developers know previous messes slow them down yet feel pressure to create new messes to meet deadlines. Martin’s answer is that keeping code clean is part of going fast.\n\nIn a real discussion, identify the smallest safe deliverable, preserve necessary checks, and explain the cost of deferred work. Do not turn the author’s emphatic position into an unsupported guarantee that every cleanup immediately saves time.')],
    'A manager requests two new features today. One touches a confusing permission rule. Write a response that includes a smaller scope and the necessary check.',
    '“I can finish the display change today. The permission change affects access decisions, so I need to clarify the rule and test allowed and denied cases before releasing it. We can ship the display work first and schedule the permission change with those checks.” This supplies consequences and options instead of quietly skipping care.')
quiz(m, 'economics-check', 'Check precision and maintenance cost', 'Precision and maintenance cost', [
    ('A generator creates code from a vague request. What responsibility remains?', ['Assume every edge case was inferred correctly', 'Define the missing behavior and check the implementation', 'Treat compilation as proof of business correctness'], 1, 'Executable behavior still requires precise requirements and verification.'),
    ('Why can adding developers to a tangled project fail to restore speed?', ['Developers never improve systems', 'A larger team automatically duplicates all features', 'Newcomers lack design context and can add more tangles under pressure'], 2, 'The source describes a feedback loop of low context, pressure and worsening change cost.'),
    ('What is the moving target in a grand redesign?', ['The replacement must match the old system while that system keeps changing', 'The old system stops receiving updates automatically', 'A new codebase cannot develop technical debt'], 0, 'Feature parity and continued changes create an ongoing race.'),
    ('What is the professional response to risky deadline pressure?', ['Hide shortcuts to protect the schedule', 'State consequences and offer a smaller safe scope', 'Promise that every rewrite takes less time'], 1, 'Provide honest engineering information and defend the work needed for a safe change.')])

m = module('definitions', '05 What clean code means')
lesson(m, 'code-sense', 'Code sense and behavior-preserving transformations', '36–37',
       'Distinguish noticing messy code from knowing how to improve it without changing its behavior.', [
    ('Recognition is not execution', 'The Art of Clean Code compares judging a painting with being able to paint. Seeing that a module is confusing does not tell you how to transform it. Code sense includes seeing alternative designs and choosing a workable sequence.\n\nThe skill is developed through small techniques and repeated decisions, not only through a vocabulary of smells.'),
    ('Refactoring preserves the contract', 'A behavior-preserving transformation changes internal structure while keeping the observable contract. A rename, extraction or movement can be a refactoring if callers still receive the same results and side effects.\n\nChanging eligibility, throwing a new error or reordering an externally meaningful sequence is a behavior change and needs its own decision. Label it honestly.'),
    ('Plan a small sequence', 'First understand the behavior. Add checks around what matters. Make one understandable transformation. Run the checks and inspect the difference. Repeat only when the next change has a clear purpose.\n\nThis is authored practice that makes the source’s transformation idea concrete. It is not a full reconstruction of a missing case study.')],
    'You rename a function and also change its result from undefined to null. Is the whole change behavior-preserving? Explain.',
    'No. The rename may preserve behavior if references are updated, but changing the result can affect callers. Separate the contract change, specify its effects and verify them. Passing one happy-path test is not evidence that every caller is unaffected.')
lesson(m, 'stroustrup-booch', 'Stroustrup and Booch: focus and clarity', '37–39',
       'Compare efficiency, focus, clear control flow and direct expression of intent.', [
    ('Bjarne Stroustrup’s emphasis', 'Stroustrup values elegant and efficient code with straightforward logic, minimal dependencies, a clear error strategy and strong performance. He emphasizes doing one thing well.\n\nMartin interprets this as attention to details including errors, resource leaks, race conditions and inconsistent naming. Wasteful execution can tempt unprincipled optimization; muddy purpose can hide bugs.'),
    ('The broken-windows connection', 'Martin connects neglected code with the broken-windows metaphor from Dave Thomas and Andy Hunt: visible disorder can encourage the next person to accept more disorder.\n\nThe metaphor describes a possible maintenance habit. It is not evidence that a single ugly line inevitably destroys a project. A small, justified improvement can change what the next reader expects.'),
    ('Grady Booch’s emphasis', 'Booch values simple, direct code that reads clearly, exposes the designer’s intent, and uses crisp abstractions and straightforward control flow. Martin interprets crispness as decisive and free from unnecessary detail.\n\nReadable code lets a reader follow the problem and see why the solution fits. Speculative structure that serves no current need can obscure that story.')],
    'Review one function for purpose, dependencies, error handling and reader effort. Name one improvement that helps both focus and clarity.',
    'Example: move unrelated reporting out of a calculation while retaining the same reporting behavior at its caller. The calculation becomes easier to explain and test. Verify the ordering and side effects; do not call the change safe merely because the extracted function is shorter.')
lesson(m, 'thomas-feathers', 'Thomas and Feathers: changeability and care', '39–40',
       'Explain why readable code also needs checks, clear dependencies and deliberate care.', [
    ('Dave Thomas’s definition', 'Dave Thomas emphasizes code another developer can read and enhance. He names unit and acceptance tests, meaningful names, one clear way to do a task, explicit minimal dependencies, and a minimal API.\n\nReadable and changeable are related but different: understanding a function does not by itself show that a change will be safe.'),
    ('Tests and literate communication', 'Martin strongly endorses tests as part of clean code. Thomas’s literate-code point recognizes that language constructs alone may not express every necessary piece of information.\n\nPreserve useful contracts or rationale where needed. This excerpt does not supply the later Comments or Unit Tests chapters, so do not claim their detailed rules are included here.'),
    ('Michael Feathers’s definition', 'Feathers emphasizes the visible care of the author: the code appears thought through, simple and orderly, with details attended to. Martin summarizes this as caring for code.\n\nCare is not decoration. A neat-looking function with a hidden failure path still needs work. Look for evidence that responsibilities, constraints and likely changes have been considered.')],
    'A function has excellent names but no tests and reads a global variable silently. Explain two remaining change risks.',
    'The result depends on hidden state, so callers and tests cannot see the whole contract. Missing tests make it harder to detect a regression. Make the dependency explicit where appropriate and add focused checks before changing it. Naming is valuable but does not establish changeability by itself.')
lesson(m, 'jeffries', 'Jeffries: simple design and small abstractions', '40–41',
       'Apply the priorities of simple code and explain the idea behind an abstraction.', [
    ('The priority order', 'Jeffries presents Beck’s simple-code rules in order: run all tests; remove duplication; express the system’s design ideas; minimize entities such as classes and methods.\n\nDo not remove an entity in a way that breaks behavior or hides the design just to win a size metric. The order matters.'),
    ('Duplication reveals a missing idea', 'Repeated behavior may mean an idea has not been represented clearly. Jeffries revisits names, asks whether an object or method does more than one thing, and uses extraction to express intent.\n\nExpressiveness extends beyond names: boundaries and responsibilities should make the system’s ideas visible. Similar syntax alone does not prove that two policies are the same idea.'),
    ('Finding things in a collection', 'Jeffries describes a small abstraction around a recurring search. It can start with a simple implementation and later change the underlying collection without changing each caller. The boundary also keeps the API focused on the searches that are actually needed.\n\nAuthored example:\n\n```js\nfunction findLessonById(lessons, lessonId) {\n  return lessons.find(lesson => lesson.id === lessonId);\n}\n```\n\nDefine what happens when no lesson matches before swapping the backing implementation.')],
    'Write the contract for findLessonById. Explain why creating a configurable repository framework for every imaginable query would not follow the small-abstraction example.',
    'The example returns the first matching lesson or undefined and does not reorder or mutate the list. A large generic framework introduces dependencies and choices beyond the current need. Preserve the lookup contract and add broader capabilities only when there is a concrete requirement. If duplicate IDs are possible, specify whether first-match behavior is acceptable.')
lesson(m, 'cunningham', 'Cunningham: unsurprising code and domain language', '41–42',
       'Explain how naming and boundaries can make the next step in a program predictable.', [
    ('A reader’s expectations', 'Cunningham’s test is whether routines turn out as a reader expects. Martin contrasts that with puzzling modules that require the reader to reconstruct tangled reasoning. Clean modules set up the next module clearly.\n\nExpectation is a contract: a lookup should not unexpectedly save data, and a name about completion should not silently mean mere visitation.'),
    ('Make the language fit the problem', 'Cunningham describes beauty when a program makes its language seem designed for the problem. Domain names and small abstractions can let code speak in terms of lessons, enrollments and completion instead of unrelated storage details.\n\nMartin puts responsibility on the programmer rather than on a favored language. No language automatically makes the design understandable.'),
    ('Use surprise as a review prompt', 'Before reading a routine, predict its inputs, result and effects from its name and call site. Then compare the prediction with the implementation.\n\nA mismatch is a reason to inspect the naming or boundary. It is not automatically a bug: a documented contract may intentionally differ from your first assumption.')],
    'A function named findLesson both returns a lesson and sends an analytics event. What question should a reviewer ask?',
    '“Is the analytics side effect part of the intended and documented lookup contract?” If it is not, consider making the effect explicit at the caller or giving the routine a name that communicates it. Verify behavior before moving it, including whether the event should occur on a failed lookup.')
quiz(m, 'definitions-check', 'Check clean-code perspectives', 'Clean-code judgment', [
    ('Which concern is central to Stroustrup’s definition?', ['Straightforward logic, efficiency and a complete error strategy', 'The largest possible framework', 'Only visual formatting'], 0, 'His perspective combines elegance, focus, dependencies, errors and efficiency.'),
    ('What does Dave Thomas add beyond ease of reading?', ['More hidden dependencies', 'Ease of enhancement supported by tests and explicit boundaries', 'An API for every possible future feature'], 1, 'Changeability, tests, minimal dependencies and a clear API are part of his definition.'),
    ('What is the first priority in Jeffries’s simple-code list?', ['Minimize the number of functions at any cost', 'Remove every repeated word', 'Run all the tests'], 2, 'The stated priority order begins with tests, then duplication, expression and entity count.'),
    ('Which routine best fits Cunningham’s expectation criterion?', ['A lookup that secretly changes permissions', 'A named lookup that follows its explicit result and side-effect contract', 'A function whose name has no relation to its behavior'], 1, 'A reader should be able to predict the routine from its intent and context.'),
    ('What does code sense add to spotting a mess?', ['A sequence of behavior-preserving improvements', 'A universal maximum line count', 'Permission to skip checking results'], 0, 'It includes seeing alternatives and choosing transformations, not just recognizing disorder.')])

m = module('authorship', '06 Writing for the next reader')
lesson(m, 'schools', 'Schools of thought and professional judgment', '42–43',
       'Use the book’s strong recommendations as a school of practice while evaluating context.', [
    ('The Object Mentor school', 'Martin explicitly presents the book as the Object Mentor School of Clean Code. Its authors state opinions strongly because they have practiced them over decades. He uses martial-arts schools as an analogy for learning a coherent approach.\n\nPractice one approach carefully enough to understand it. Later, broaden your understanding with other approaches.'),
    ('Strong guidance is not final authority', 'The text also says other schools can be professional and that some recommendations are controversial. Disagreement can coexist with respect for the reasoning and experience behind a practice.\n\nEvaluate a recommendation against behavior, readers, change cost and evidence. Avoid treating every aesthetic preference as an absolute correctness rule.'),
    ('Separate principle from local convention', 'A principle such as communicating intent can support several naming conventions. Team consistency and a demonstrated reader benefit can matter more than adopting the author’s exact spelling choices.\n\nIn a review, state the problem and consequence before proposing a convention. “I prefer it” is different from “this name leads callers to expect the wrong result.”')],
    'Two teammates disagree about a helper extraction. Write one question that tests whether the extraction is useful rather than asking who follows the right school.',
    '“Can a reader now identify the responsibility and safely change it with less surrounding context?” Also check whether the helper hides important behavior or creates indirection without a benefit. Use a concrete call site and test, not a slogan.')
lesson(m, 'authors', 'We are authors and code is read repeatedly', '43–44',
       'Explain why improving reader comprehension can help future changes.', [
    ('Programmers have readers', 'The chapter compares a programmer with an author responsible for communication. Readers include teammates and your future self. A line of code contributes to a larger explanation of the problem and solution.\n\nNames, structure, contracts and direct control flow should help that reader reconstruct the intent.'),
    ('The edit-session observation', 'Martin describes replaying edit sessions in which much of the time was spent scrolling, inspecting initialization, checking callers and examining subclasses. He argues that reading greatly exceeds writing and gives a ratio above 10:1.\n\nTreat that ratio as the author’s observation and argument, not a measured ratio for every developer. The supported practical point is that writing a change requires understanding surrounding code.'),
    ('Reduce the cost of understanding', 'Ask what the reader must discover before editing: where data comes from, which callers depend on it, what a flag means and whether an effect happens. Make necessary information easy to find.\n\nA shorter function is not automatically easier to read if it scatters one coherent idea across many poorly named helpers. Evaluate reader effort in context.')],
    'Describe one time you had to inspect several files before making a small change. What information would have reduced that search?',
    'A clear contract, explicit dependency, meaningful name or focused test could answer the question locally. For example, a test stating that a missing lesson returns undefined removes guesswork. Record the actual missing information before rearranging code.')
lesson(m, 'boy-scout', 'The Boy Scout Rule and continuous improvement', '44',
       'Choose a small cleanup that leaves the code easier to maintain.', [
    ('Keep the code clean over time', 'The Boy Scout Rule applies the campground principle to code: leave it a little better than you found it. Writing clean code once is insufficient if later changes let it decay.\n\nThe source names improved variable names, breaking a large function, removing small duplication and simplifying a composite condition as possible small cleanups.'),
    ('Make a bounded improvement', 'Choose a change related to the work you understand. Describe the expected benefit, keep the difference reviewable and verify behavior. Continuous care does not require a whole-system rewrite during every bug fix.\n\nAn authored example replaces an unexplained flag name with isCompleted while preserving its boolean meaning and updating its references.'),
    ('Review the consequence', 'Ask: Did I clarify a real ambiguity? Did I preserve behavior? Did I introduce a new dependency? Can the next person understand the improvement?\n\nIf cleanup needs a contract change, separate and explain it. The rule is an attitude of maintenance, not permission to hide unrelated work in a small commit.')],
    'Choose exactly one cleanup in a function you understand. Write a before/after reason and the check you will run.',
    '“Rename d to completedAt because the value is a completion timestamp, not a duration. Update all references and run the completion tests.” The reason communicates the value’s meaning; the check helps show that the rename preserved behavior.')
lesson(m, 'principles-conclusion', 'Principles, bibliography and the limits of reading', '45',
       'Recognize the chapter’s follow-up references and why practice remains necessary.', [
    ('Prequel and principles', 'Martin describes Clean Code as a prequel to his 2002 Agile Software Development: Principles, Patterns, and Practices (PPP). He names the Single Responsibility Principle (SRP), Open Closed Principle (OCP) and Dependency Inversion Principle (DIP), and says PPP describes them in depth.\n\nThis excerpt does not give their full explanations. A reference to a principle is not the same as a complete lesson on it.'),
    ('What a book can provide', 'The conclusion compares a programming book to a book about art. It can expose tools, thought processes, good and bad examples and transformations. It cannot promise to make a reader skilled or automatically provide code sense.\n\nThe reader must practice, inspect outcomes and revise decisions.'),
    ('Use references honestly', 'The chapter bibliography points to Implementation Patterns by Kent Beck and Literate Programming by Donald E. Knuth. The full index points into missing parts of the book as well as available pages.\n\nPreserve the references so you can follow up. Do not claim that this course includes the entire contents of those other works.')],
    'Write a follow-up learning plan containing one available concept, one code exercise and one genuinely missing chapter or principle reference.',
    'Available concept: reader expectations. Exercise: make one lookup’s contract explicit and test not-found behavior. Missing follow-up: read the actual Unit Tests chapter or PPP’s principle explanations. This distinguishes learning from the supplied material from obtaining additional sources.')
quiz(m, 'reader-check', 'Check authorship and ongoing care', 'Authorship and continuous improvement', [
    ('How does Martin describe his school of thought?', ['The only professional approach with final authority', 'A practiced approach that can be learned alongside other schools', 'A set of rules that cannot be questioned'], 1, 'The chapter acknowledges controversy and other professional schools.'),
    ('What supports making code easy to read?', ['A change requires understanding surrounding code', 'Readers only inspect formatting', 'Generated code has no readers'], 0, 'The edit-session argument links reader comprehension to effective modification.'),
    ('Which change best illustrates a bounded Boy Scout cleanup?', ['Rewrite the entire application without a plan', 'Hide an eligibility change inside a rename', 'Clarify one misleading name and verify its references'], 2, 'A small, justified, behavior-preserving improvement is enough.'),
    ('What is actually present about SRP, OCP and DIP?', ['Full chapters and implementations', 'Their names and a follow-up reference to PPP', 'A formal proof for each principle'], 1, 'The excerpt mentions the principles but directs deeper study to another book.')])

m = module('practice', '07 Refactoring clinic')
lesson(m, 'clinic', 'Refactor a lesson lookup without changing its contract', '37, 40–44',
       'Practice naming, one responsibility, simple abstraction and verification in an original JavaScript example.', [
    ('Establish behavior first', 'Authored example, not a book listing. We search in array order, return the first matching object, return undefined if absent, and do not mutate the list. Inputs are an array of lesson records and an ID.\n\n```js\nfunction f(a, x) {\n  for (let i = 0; i < a.length; i++) {\n    if (a[i].id === x) return a[i];\n  }\n  return undefined;\n}\n```\n\nThe main problem is unclear intent. Do not silently add validation or a different not-found result while renaming it.'),
    ('Name the idea', 'Authored refactoring:\n\n```js\nfunction findLessonById(lessons, lessonId) {\n  for (let index = 0; index < lessons.length; index++) {\n    if (lessons[index].id === lessonId) {\n      return lessons[index];\n    }\n  }\n  return undefined;\n}\n```\n\nThe function now tells a reader what the search means. The result and order are unchanged. Keeping the loop for this step makes the transformation easy to review.'),
    ('Check meaningful cases', 'Authored checks:\n\n```js\nconst first = { id: "lesson-1", title: "Care" };\nconst laterDuplicate = { id: "lesson-1", title: "Other" };\nconst lessons = [first, laterDuplicate];\nconsole.assert(findLessonById(lessons, "lesson-1") === first);\nconsole.assert(findLessonById(lessons, "missing") === undefined);\nconsole.assert(findLessonById([], "lesson-1") === undefined);\nconsole.assert(lessons[0] === first && lessons.length === 2);\n```\n\nThese cases cover first-match, missing, empty and unchanged input. They do not claim support for invalid inputs.'),
    ('Consider the next improvement', 'With the contract established, Array.find may make the search idea more direct. Check the same cases before accepting the change. A Map implementation can change duplicate-ID behavior unless you deliberately preserve first-match semantics.\n\nOne abstraction permits a later implementation change; it does not make that change automatically safe.')],
    'Replace the loop with Array.find. Run the checks, then explain why a Map constructed from all records can return the wrong duplicate.',
    '```js\nfunction findLessonById(lessons, lessonId) {\n  return lessons.find(lesson => lesson.id === lessonId);\n}\n```\n\nfind returns the first match, or undefined. A Map constructed with repeated keys normally keeps the last value, so it could return laterDuplicate. That would change the stated contract even though the implementation looked cleaner.')
lesson(m, 'review-capstone', 'Capstone review and your next small change', '19–45',
       'Combine the source’s perspectives into an evidence-based review of a small module.', [
    ('Build a review in five questions', '1. **Intent:** Can a reader predict this routine?\n2. **Behavior:** Are normal, missing and failure cases explicit and checked?\n3. **Focus:** Is one responsibility obscured by unrelated effects?\n4. **Changeability:** Are dependencies and shared ideas clear?\n5. **Care:** What one justified improvement can I leave behind?\n\nThis checklist is an authored synthesis of the excerpt, not the missing Smells and Heuristics chapter.'),
    ('Make a claim with evidence', 'Weak review: “This is bad code.”\n\nUseful review: “The function is named findLesson, but it also updates completion. A caller cannot predict that side effect from the name. Please make the update explicit and verify both successful and missing lookups.”\n\nState the concrete trigger, consequence and proposed check. Do not require an extraction only because a line count is high.'),
    ('Record the change', 'Write a short before/after note: original behavior, reader difficulty, chosen transformation, checks passed, remaining uncertainty.\n\nA passing module quiz shows recall and judgment in these scenarios. Only working on real code provides evidence about your ability to make a safe change.')],
    'Select a real helper from one of your projects. Explain it without looking at the implementation, compare that explanation with the code, and make one behavior-preserving improvement. Keep the diff and your checks.',
    'The submission is your explanation, a bounded diff and check results. A valid outcome may be “No change needed; the routine already matches its contract.” If a behavior change is necessary, identify it separately. The goal is deliberate judgment and care, not the greatest number of edits.')
quiz(m, 'practice-check', 'Check refactoring decisions', 'Behavior-preserving refactoring', [
    ('The original lookup returns the first duplicate ID. Which replacement preserves that contract?', ['Array.find with the same equality check', 'A Map that overwrites earlier duplicate keys', 'Always return the last matching record'], 0, 'Array.find retains first-match behavior. The other choices select a later value.'),
    ('Which check addresses a meaningful lookup boundary?', ['Only check whether the function name is short', 'Verify that a missing ID returns undefined', 'Only count the number of lines'], 1, 'Not-found behavior is part of the explicit contract and can regress during refactoring.'),
    ('Which review comment is most useful?', ['This feels wrong', 'All functions must have three lines', 'This lookup changes completion unexpectedly; make the effect explicit and test it'], 2, 'A concrete mismatch, its consequence and a verification request support a reviewable decision.')])

# Preserve every uploaded text page, not only teaching passages. No OCR or rewriting.
text_path = ROOT / 'docs/clean-code-extracted.txt'
text = text_path.read_text(encoding='utf-8')
matches = list(re.finditer(r'^\[PDF page (\d+)\]\n\n', text, re.M))
pages = []
for i, match in enumerate(matches):
    end = matches[i+1].start() if i+1 < len(matches) else len(text)
    pages.append((int(match[1]), text[match.end():end].rstrip('\n')))
assert [p[0] for p in pages] == list(range(1,68)), 'Expected all 67 pages in order'
archive = module('source-reference', '08 Complete source reference')
ranges = [('publication', 'Publication pages and credits', 1,6), ('contents', 'Complete contents',7,18), ('source-foreword','Foreword',19,24), ('source-introduction','Introduction acknowledgments and cover',25,30), ('source-chapter-one-a','Chapter 1 Code and its cost',31,36), ('source-chapter-one-b','Chapter 1 Clean code and authorship',37,46), ('index-a','Index pages 413–422',47,56), ('index-b','Index pages 423–431',57,65), ('advertisement','Publisher offers',66,67)]
page_manifest = []
for id,title,start,end in ranges:
    slides = []
    for n,page in pages[start-1:end]:
        sid = f'pdf-page-{n:02}'
        slides.append(dict(id=sid, title=f'{title} — PDF page {n}', body='```text\n'+page+'\n```'))
        page_manifest.append(dict(pdfPage=n, lessonId=id, slideId=sid, textSha256=hashlib.sha256(page.encode()).hexdigest(), characters=len(page)))
    archive['children'].append(dict(id=id,type='slides',title=f'{title} · PDF {start}–{end}',slides=slides))

final_questions = [
    ('A teammate marks a lesson complete when it is opened. The requested rule is “complete after every slide is reviewed.” What should you do first?', ['Specify and check the actual completion contract', 'Change the button color only', 'Assume opening and reviewing mean the same thing'],0,'Resolve the precise requirement before judging or changing its implementation.'),
    ('Your cleanup deletes a no-match return because null looks clearer. The callers distinguish null and undefined. How should you classify the edit?', ['A formatting-only change', 'A behavior change that needs a separate decision and checks', 'Automatically safe because it is shorter'],1,'Changing an observable result is not behavior-preserving refactoring.'),
    ('Two helpers share syntax but implement different domain policies. What is the best next step?', ['Merge them immediately to remove lines', 'Delete one policy', 'Explain their meanings and change patterns before choosing an abstraction'],2,'An abstraction should express a shared idea, not conceal different requirements behind similar syntax.'),
    ('A bug fix includes a safe rename of a misleading flag and focused checks. Which source idea does this best apply?', ['The grand redesign race', 'The Boy Scout Rule', 'Replacing practice with reading'],1,'A bounded improvement leaves the code a little easier to maintain.'),
    ('An apparently simple function silently reads global state. Which clean-code concern remains?', ['Its hidden dependency makes behavior and changes harder to reason about', 'Its font choice is incorrect', 'It must be replaced with the largest framework'],0,'Thomas emphasizes explicit dependencies and changeability, beyond readability alone.'),
    ('A product’s releases slow after copied rules diverge. Which account best fits the source’s maintenance argument?', ['More copying necessarily increases speed', 'All delays are caused by the programming language', 'Tangles increase understanding and regression costs, creating pressure for further shortcuts'],2,'The source describes an accumulating cycle, not a numeric law about every project.'),
    ('A new team promises a rewrite, but the old app keeps gaining features. What must the plan account for?', ['Matching current behavior and keeping up with a moving target', 'Assuming all legacy behavior is irrelevant', 'The impossibility of messy new code'],0,'A replacement race requires parity plus ongoing changes; new code can also accumulate disorder.'),
    ('An unfamiliar convention differs from the book but communicates intent and fits the team. What is an appropriate response?', ['Reject it solely because another school uses a different convention', 'Evaluate reader benefit, behavior and consistency in context', 'Ignore the team’s agreed practices'],1,'The Schools of Thought passage acknowledges professional alternatives and encourages broadening judgment.'),
    ('A reader can predict a lookup from its name and its documented contract. Which perspective does this especially illustrate?', ['Cunningham’s expectation criterion', 'A guarantee of zero defects', 'The need for hidden side effects'],0,'Cunningham values routines that behave as a reader expects; this does not guarantee correctness.'),
    ('A developer says “We can skip tests because the code is elegant.” Which response best reflects Thomas and Jeffries?', ['Agree whenever there are fewer lines', 'Only names matter', 'Checks support safe enhancement, and passing tests comes first in the simple-code priority order'],2,'Both perspectives include tests; elegance alone does not establish safe changeability.'),
    ('The contents name Concurrency and JUnit Internals. What can this course honestly claim?', ['It contains those full chapters', 'It preserves their contents/index references; their chapter text is absent', 'It reconstructed the author’s missing listings'],1,'Full coverage is of the supplied 67 pages, not unavailable chapters in the complete book.'),
    ('Which final artifact best demonstrates practice rather than recall alone?', ['A copied definition with no application', 'A slide completion count', 'An explained contract, a small diff and behavior checks from your own project'],2,'The introduction and conclusion emphasize applying decisions and learning through work.')
]
course = dict(schemaVersion=1,id='clean-code-excerpt-course-v1',title='Clean Code',description='Study the complete supplied 67-page excerpt: care, maintenance, precise requirements, clean-code judgment, authorship and small refactorings. Guided practice and quizzes accompany a full page-ordered text reference.',sections=sections,finalQuiz=dict(id='clean-code-final',type='quiz',title='Final assessment',skill='Integrated clean-code judgment',questions=[dict(id=f'final-q{i}',prompt=p,options=o,answer=a,explanation=e) for i,(p,o,a,e) in enumerate(final_questions,1)]),settings=dict(passScore=80,allowRetakes=True,showLessonDetails=False,unlockAll=True,sequential=False,requireLessons=True,brand='#bbbcef',background='#070b15',surface='#0b2646',text='#e0dcf8',muted='#bbbcef',border='#6286d3',fontScale=1,spacing=28,contentWidth=980,radius=0,font='humanist',headingFont='humanist',lineHeight=1.65))
