nodes=[]
def walk(ns):
    for n in ns:
        if n['type']=='section': walk(n['children'])
        else: nodes.append(n)
walk(sections)
print(json.dumps(dict(modules=len(sections),decks=sum(n['type']=='slides' for n in nodes),guidedDecks=len(coverage),slides=sum(len(n.get('slides',[])) for n in nodes),moduleQuizzes=sum(n['type']=='quiz' for n in nodes),moduleQuestions=sum(len(n.get('questions',[])) for n in nodes),finalQuestions=len(final_questions),sourcePages=len(page_manifest))))
